{
  "duration_weeks": 12,
  "phases": [
    {
      "name": "Prep / Pain-management",
      "weeks": 3,
      "focus": "Restore pain-free movement, build scapular control and rotator cuff endurance without overhead loading."
    },
    {
      "name": "Strength Foundation",
      "weeks": 5,
      "focus": "Increase horizontal and pulling strength, progressive loading within pain-free range, emphasize scapular stability."
    },
    {
      "name": "Load Progression & Capacity",
      "weeks": 4,
      "focus": "Increase force production and muscular endurance for climbing-related upper-body demands while maintaining shoulder safety."
    }
  ],
  "weekly_template": {
    "days_per_week": 4,
    "day_types": [
      "Horizontal Push + Scapular Control",
      "Pull Emphasis + Rotator Cuff",
      "Active Recovery / Mobility + Core",
      "Mixed Upper Strength (no overhead) + Grip"
    ]
  },
  "non_negotiables": [
    "Pain-free range only",
    "No overhead loading",
    "Follow physio guidance for ROM and exercise progressions",
    "Stop and regress any exercise that produces sharp or increasing shoulder pain"
  ]
}
